const users = [{ name: "Kakade" }, { name: "Asha" }, { name: "Rohan" }];

function renderTeam(users) {
  const template = document.getElementById("row");
  const fragment = document.createDocumentFragment();

  for (const user of users) {
    const node = template.content.cloneNode(true);
    node.querySelector(".name").textContent = user.name;
    fragment.append(node);
  }

  document.getElementById("team").append(fragment);
}

renderTeam(users);
// <ul id="team"> with three li.row elements: Kakade, Asha, Rohan

Template content is inert until cloned, so cloneNode(true) is required for every row — appending content directly would move its children and leave nothing for the next iteration. All rows are built off-DOM inside the fragment, then inserted with one append, so the browser performs one insertion instead of three. textContent sets the name safely; no HTML parsing and no XSS. If the list is re-rendered, clear it first or reuse nodes deliberately.

