function buildCard(user) {
  const card = document.createElement("article");
  card.className = "card";
  card.dataset.userId = user.id;

  const name = document.createElement("h3");
  name.textContent = user.name;

  const bio = document.createElement("p");
  bio.textContent = user.bio;

  card.append(name, bio);
  return card;
}

const card = buildCard({ id: 7, name: "Kakade", bio: "Frontend developer" });
document.body.append(card);
// <article class="card" data-user-id="7"><h3>Kakade</h3><p>Frontend developer</p></article>

createElement plus textContent makes every value a text node, so a name like <img onerror=...> is displayed, not executed. dataset.userId writes the data-user-id attribute and stringifies the number. append accepts several children in one call. The function returns a detached element, which makes it easy to test and lets the caller decide where to insert it. Setting className replaces all classes; classList.add is better when preserving existing ones.

